//frontend/src/pages/Login.js
import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { loginUser } from '../services/api'; // Importa la función para llamar al backend
function Login() {
    const [correo, setCorreo] = useState('');
    const [contraseña, setContraseña] = useState('');
    const [error, setError] = useState('');
    const navigate = useNavigate();
  
    const handleSubmit = async (event) => {
      event.preventDefault();
      setError(''); // Limpia cualquier error previo
  
      try {
        const data = await loginUser({ correo, contraseña });
        // Aquí deberías guardar el token y la información del usuario (lo haremos en el siguiente paso)
        console.log('Inicio de sesión exitoso:', data);
        navigate('/dashboard'); // Redirige al dashboard después del éxito
      } catch (error) {
        console.error('Error al iniciar sesión:', error);
        setError(error.message || 'Error al iniciar sesión. Por favor, intenta de nuevo.');
      }
    };
  
    return (
      <div>
        <h2>Iniciar Sesión</h2>
        {error && <p style={{ color: 'red' }}>{error}</p>}
        <form onSubmit={handleSubmit}>
          <div>
            <label htmlFor="correo">Correo Electrónico:</label>
            <input
              type="email"
              id="correo"
              value={correo}
              onChange={(e) => setCorreo(e.target.value)}
              required
            />
          </div>
          <div>
            <label htmlFor="contraseña">Contraseña:</label>
            <input
              type="password"
              id="contraseña"
              value={contraseña}
              onChange={(e) => setContraseña(e.target.value)}
              required
            />
          </div>
          <button type="submit">Iniciar Sesión</button>
        </form>
        <p>¿No tienes una cuenta? <Link to="/register">Regístrate</Link></p> {/* Importa Link de react-router-dom */}
      </div>
    );
  }
  
  export default Login;
